cd /home/judge/solution; grep -n ENV_FILE bozshakol/tools/twinctl.py | head -2; P=$(grep -h '^DITTO_PASSWORD=' .env deploy/*/.env 2>/dev/null | head -1 | cut -d= -f2); echo "pw len ${#P}"; echo "$P" > /tmp/dp; curl -s -u ditto:$P localhost:8080/api/2/things/kz.bozshakol:control/features | head -c 1500; echo; curl -s -u ditto:$P localhost:8080/api/2/things/kz.bozshakol:whatif/features > /tmp/w0.json; python3 -c "
import json;d=json.load(open('/tmp/w0.json'))
for k,v in d.items():
  p=v.get('properties',{})
  for kk,vv in p.items():
    if any(s in kk for s in ['exposed','month_ore','status','scenario','updated','calc']): print(k,kk,vv)
"

